cat > /tmp/opencode/qa/scan.py <<'EOF'
import re, sys, glob, os
sys.path.insert(0,'/app/categorizationapp')
import importlib
BR = importlib.import_module('categorizationapp.UtilityScripts.BankRegexConstants')
RC = importlib.import_module('categorizationapp.UtilityScripts.RegexConstants')
consts = {}
for m in (BR, RC):
    for k,v in vars(m).items():
        if isinstance(v,str) and k.isupper(): consts[k]=v

pat_call = re.compile(r'py_extract\(\s*([^,]+?),\s*(?:pat=)?(.+?),\s*index\s*=\s*(\d+)\s*\)', re.S)
for f in sorted(glob.glob('/app/categorizationapp/categorizationapp/**/*.py', recursive=True)):
    src = open(f).read()
    for i, line in enumerate(src.split('\n'), 1):
        for m in pat_call.finditer(line):
            patexpr, idx = m.group(2).strip(), int(m.group(3))
            pat = None
            if patexpr.startswith('"') and patexpr.endswith('"'):
                pat = patexpr[1:-1].encode().decode('unicode_escape')
            elif patexpr in consts:
                pat = consts[patexpr]
            if pat is None: 
                continue
            try:
                ng = re.compile(pat).groups
            except Exception as e:
                print(f"BADRE {f}:{i} {patexpr} {e}"); continue
            if idx >= ng:
                print(f"IDX>{ng-1} {os.path.relpath(f,'/app')}:{i}  index={idx} groups={ng}  pat={pat!r}")
EOF
