import re, glob, os
defs = {}
for f in ['UtilityScripts/BankRegexConstants.py','UtilityScripts/RegexConstants.py']:
    for i,l in enumerate(open(f), 1):
        m = re.match(r'^([A-Z][A-Z0-9_]*)\s*=', l)
        if m: defs[m.group(1)] = (f,i)
src = ""
for f in glob.glob('**/*.py', recursive=True):
    if 'RegexConstants' in f: continue
    src += open(f).read()
unused = [(k,v) for k,v in defs.items() if not re.search(r'\b'+k+r'\b', src)]
for k,(f,i) in sorted(unused, key=lambda x:(x[1][0],x[1][1])):
    print(f"{f}:{i} {k}")
print(len(unused), "unused of", len(defs))
EOF

